import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";

/*
 * Layout uses logical properties only, so the screen mirrors for Arabic and Urdu (DESIGN.md,
 * Layout). The shadcn output in src/components/ui is generated by the CLI with `rtl: true`
 * and is the only place exempt from this scan.
 */

const srcRoot = path.resolve(import.meta.dirname, "../../../src");

/*
 * Margin, padding and inset sides (and their scroll-* twins), the physical border and radius sides
 * (with or without a width/size suffix), and text/float/clear alignment.
 */
const PHYSICAL =
  /\b(?:ml|mr|pl|pr|left|right|scroll-ml|scroll-mr|scroll-pl|scroll-pr)-[\w[]|\b(?:rounded|border)-(?:l|r|tl|tr|bl|br)(?:-[\w[]|(?![\w-]))|\b(?:text|float|clear)-(?:left|right)\b/;

function scannedFiles(): string[] {
  return readdirSync(srcRoot, { recursive: true, encoding: "utf8" })
    .map((entry) => entry.split(path.sep).join("/"))
    .filter((entry) => entry.endsWith(".tsx") && !entry.startsWith("components/ui/"))
    .sort();
}

function flagged(cls: string): boolean {
  return PHYSICAL.test(`className="${cls}"`);
}

describe("no physical direction classes", () => {
  const files = scannedFiles();

  it("scans a non-trivial set of files and skips the shadcn output", () => {
    expect(files.length).toBeGreaterThan(0);
    expect(files.some((f) => f.startsWith("components/ui/"))).toBe(false);
  });

  it.each([
    "ml-4",
    "-ml-2",
    "sm:mr-auto",
    "pl-[3px]",
    "pr-2",
    "left-0",
    "right-4",
    "text-left",
    "text-right",
    "rounded-l-md",
    "rounded-r",
    "rounded-tl-lg",
    "border-l-2",
    "border-r",
    "float-left",
    "scroll-pl-4",
  ])("flags the physical utility %s", (cls) => {
    expect(flagged(cls)).toBe(true);
  });

  it.each([
    "ms-4",
    "me-auto",
    "ps-2",
    "pe-4",
    "start-0",
    "end-4",
    "text-start",
    "text-end",
    "rounded-s-sm",
    "rounded-sign",
    "border-s-2",
    "border-hairline",
    "float-start",
    "inset-x-0",
  ])("accepts %s", (cls) => {
    expect(flagged(cls)).toBe(false);
  });

  it.each(files)("%s has none", (file) => {
    const source = readFileSync(path.join(srcRoot, file), "utf8");
    expect(PHYSICAL.exec(source)?.[0]).toBeUndefined();
  });
});
